SELECT 
	*
FROM
	SSIAD
WHERE HOUSE_CODE 	= ${HOUSE_CODE}
  AND COMPANY_CODE 	= ${COMPANY_CODE}
  AND SMR_NUMBER 	= ${SMR_NUMBER}
  AND SMR_STATUS 	= 'DR'


		SELECT
			 HOUSE_CODE
			,COMPANY_CODE
			,CONT_NO
			,CONT_GL_SEQ
			,CONT_STATUS
			,CONT_SUBJECT
			,CATEGORY
			,INNER_MANAGER_NAME
			,EXT_EX_INNER_IRS_NO
			,EXT_EX_OUTER_IRS_NO
			,OUTER_COMPANY_NAME
			,OUTER_MANAGER_NAME
			,CONT_FROM
			,CONT_TO
			,CONT_DATE
			,CONT_METHOD
		FROM
			CONTRACT_HISTORY
		WHERE
			HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
			AND CONT_NO = $S{CONT_NO}
			AND CONT_GL_SEQ = $S{CONT_GL_SEQ}
			AND (
				1=1
				AND CONT_STATUS = $S{F_STATUS}
				AND CATEGORY = $S{F_CATEGORY}
				AND CONT_METHOD = $S{F_CONT_METHOD}
				AND (
					1=1
					AND CONT_SUBJECT LIKE CONCAT('%', $S{F_KEYWORD}, '%')
					OR INNER_MANAGER_NAME LIKE CONCAT('%' , $S{F_KEYWORD} , '%')
					OR EXT_EX_INNER_IRS_NO LIKE CONCAT('%' , $S{F_KEYWORD} , '%')
					OR EXT_EX_OUTER_IRS_NO LIKE CONCAT('%' , $S{F_KEYWORD} , '%')
					OR OUTER_COMPANY_NAME LIKE CONCAT('%' , $S{F_KEYWORD} , '%')
					OR OUTER_MANAGER_NAME LIKE 'CONCAT(%' , $S{F_KEYWORD} , '%')
				)
			)



        	AND ADD_DATE	>= $S{F_CALENDAR_FROM}
			AND ADD_DATE	<= $S{F_CALENDAR_TO}




        	AND CONT_DATE	>= $S{F_CALENDAR_FROM}
			AND CONT_DATE	<= $S{F_CALENDAR_TO}




        	AND CONT_FROM	>= $S{F_CALENDAR_FROM}
			AND CONT_TO		<= $S{F_CALENDAR_TO}


