	,CONT_STATUS
	,CONT_SUBJECT
	,CATEGORY
	,INNER_MANAGER_NAME
	,EXT_EX_INNER_IRS_NO
	,EXT_EX_OUTER_IRS_NO
	,OUTER_COMPANY_NAME
	,OUTER_MANAGER_NAME
	,CONT_FROM
	,CONT_TO
	,CONT_DATE
	,CONT_METHOD
) VALUES (
	 ${session.HOUSE_CODE}
	,${session.COMPANY_CODE}
	,${CONT_NO}
	,${CONT_GL_SEQ}
	,${CONT_STATUS}
	,${CONT_SUBJECT}
	,${CATEGORY}
	,${INNER_MANAGER_NAME}
	,${EXT_EX_INNER_IRS_NO}
	,${EXT_EX_OUTER_IRS_NO}
	,${OUTER_COMPANY_NAME}
	,${OUTER_MANAGER_NAME}
	,${CONT_FROM}
	,${CONT_TO}
	,${CONT_DATE}
	,${CONT_METHOD}
)


DELETE FROM CONTRACT_HISTORY
WHERE HOUSE_CODE = ${session.HOUSE_CODE}
AND COMPANY_CODE = ${session.COMPANY_CODE}
AND CONT_NO = ${CONT_NO}
AND CONT_GL_SEQ = ${CONT_GL_SEQ}


